#include <vector>
using namespace std;

class Solution {
public:
    vector<int> decode(vector<int>& encoded) {
        int n = encoded.size() + 1;
        int total_xor = 0;
        for (int i = 1; i <= n; ++i) total_xor ^= i;
        int odd_xor = 0;
        for (int i = 1; i < encoded.size(); i += 2) odd_xor ^= encoded[i];
        int first = total_xor ^ odd_xor;
        vector<int> perm;
        perm.reserve(n);
        perm.push_back(first);
        for (int x : encoded) {
            perm.push_back(perm.back() ^ x);
        }
        return perm;
    }
};

class Solution {
    public int[] decode(int[] encoded) {
        int n = encoded.length + 1;
        int totalXor = 0;
        for (int i = 1; i <= n; ++i) totalXor ^= i;
        int oddXor = 0;
        for (int i = 1; i < encoded.length; i += 2) oddXor ^= encoded[i];
        int first = totalXor ^ oddXor;
        int[] perm = new int[n];
        perm[0] = first;
        for (int i = 0; i < encoded.length; ++i) {
            perm[i + 1] = perm[i] ^ encoded[i];
        }
        return perm;
    }
}

